import{_ as e,o as l,c as t,a0 as i}from"./chunks/framework.BZ80FTt7.js";const _=JSON.parse('{"title":"2026-06-28：博客从这里开始","description":"","frontmatter":{},"headers":[],"relativePath":"blog/2026-06-28.md","filePath":"blog/2026-06-28.md"}'),r={name:"blog/2026-06-28.md"};function o(n,a,s,h,d,c){return l(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="_2026-06-28-博客从这里开始" tabindex="-1">2026-06-28：博客从这里开始 <a class="header-anchor" href="#_2026-06-28-博客从这里开始" aria-label="Permalink to &quot;2026-06-28：博客从这里开始&quot;">​</a></h1><h2 id="现状" tabindex="-1">现状 <a class="header-anchor" href="#现状" aria-label="Permalink to &quot;现状&quot;">​</a></h2><p>6 月 22 号搭好了 VitePress 博客框架，之后几天在忙别的（考试、任务、状态调整），一直没真正开始写。</p><p>今天是 28 号，决定从今天起正经记录。</p><h2 id="已完成-6-天前的事" tabindex="-1">已完成（6 天前的事） <a class="header-anchor" href="#已完成-6-天前的事" aria-label="Permalink to &quot;已完成（6 天前的事）&quot;">​</a></h2><ul><li>VitePress 博客框架搭好了</li><li>首页、Projects、Roadmap、About、Contact 五个页面都写好了</li><li>桌面放了双击启动脚本</li><li>踩了 BOM 编码的坑（GBK 误当 UTF-8 导致乱码）</li></ul><h2 id="这-6-天为什么没写" tabindex="-1">这 6 天为什么没写 <a class="header-anchor" href="#这-6-天为什么没写" aria-label="Permalink to &quot;这 6 天为什么没写&quot;">​</a></h2><ul><li>一开始想&quot;等准备好了再写&quot;，但发现永远准备不好</li><li>觉得第一篇要写得很正式，结果迟迟不敢动笔</li><li>后来想明白：博客是写给自己的，真实 &gt; 完美</li></ul><h2 id="接下来要做的" tabindex="-1">接下来要做的 <a class="header-anchor" href="#接下来要做的" aria-label="Permalink to &quot;接下来要做的&quot;">​</a></h2><ul><li>[ ] 写一篇 C++ 工程基础怎么补的文章</li><li>[ ] 跑通第一个 CMake 工程</li><li>[ ] 部署到 GitHub Pages</li></ul><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p>博客已经搭好 6 天了，今天才真正开始。剩下的就是一直写下去。</p>',12)])])}const p=e(r,[["render",o]]);export{_ as __pageData,p as default};
